fun uniquePaths(m: Int, n: Int): Int {
    val dp = Array(m) { IntArray(n) { 1 } }          // first row and first column have exactly one path
    for (r in 1 until m) {
        for (c in 1 until n) {
            dp[r][c] = dp[r - 1][c] + dp[r][c - 1]   // arrive from above or from the left
        }
    }
    return dp[m - 1][n - 1]
}
// Time: O(m * n)   Space: O(m * n)

fun uniquePathsOptimized(m: Int, n: Int): Int {
    val dp = IntArray(n) { 1 }                       // dp[c] holds the value for the current row
    for (r in 1 until m) {
        for (c in 1 until n) {
            dp[c] += dp[c - 1]                       // dp[c] (above) + dp[c - 1] (left, already updated)
        }
    }
    return dp[n - 1]
}
// Time: O(m * n)   Space: O(n)
// Works when a cell depends only on the previous row and cells to its left

fun gridPathsMemo(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    val memo = Array(rows) { IntArray(cols) { -1 } }

    fun solve(r: Int, c: Int): Int {
        if (r == rows - 1 && c == cols - 1) return grid[r][c]
        if (memo[r][c] != -1) return memo[r][c]
        var best = Int.MAX_VALUE
        if (r + 1 < rows) best = minOf(best, solve(r + 1, c))
        if (c + 1 < cols) best = minOf(best, solve(r, c + 1))
        memo[r][c] = grid[r][c] + best
        return memo[r][c]
    }

    return solve(0, 0)
}
// Time: O(rows * cols)   Space: O(rows * cols) plus recursion
// Handy when the fill order is awkward

fun minPathWithRoute(grid: Array<IntArray>): Pair<Int, List<Pair<Int, Int>>> {
    val rows = grid.size
    val cols = grid[0].size
    val dp = Array(rows) { IntArray(cols) }
    dp[0][0] = grid[0][0]
    for (c in 1 until cols) dp[0][c] = dp[0][c - 1] + grid[0][c]
    for (r in 1 until rows) dp[r][0] = dp[r - 1][0] + grid[r][0]
    for (r in 1 until rows) {
        for (c in 1 until cols) {
            dp[r][c] = grid[r][c] + minOf(dp[r - 1][c], dp[r][c - 1])
        }
    }

    // walk backward from the end, always stepping to the cheaper predecessor
    val route = ArrayList<Pair<Int, Int>>()
    var r = rows - 1
    var c = cols - 1
    route.add(Pair(r, c))
    while (r > 0 || c > 0) {
        if (r == 0) c--
        else if (c == 0) r--
        else if (dp[r - 1][c] <= dp[r][c - 1]) r--
        else c--
        route.add(Pair(r, c))
    }
    route.reverse()
    return Pair(dp[rows - 1][cols - 1], route)
}
// Time: O(rows * cols)   Space: O(rows * cols), the full table is needed to rebuild the route

// dp[l][r] = best answer for the range l..r
fun intervalDpSkeleton(n: Int): Int {
    val dp = Array(n) { IntArray(n) }
    for (len in 2..n) {                              // solve short ranges first
        for (l in 0..n - len) {
            val r = l + len - 1
            for (k in l until r) {                   // try every split point
                // dp[l][r] = best(dp[l][r], dp[l][k] + dp[k + 1][r] + costOfMerging(l, k, r))
            }
        }
    }
    return dp[0][n - 1]
}
// Time: O(n³)   Space: O(n²)

// dp[i][j] = answer for the first i characters of a and the first j characters of b
fun twoSequenceSkeleton(a: String, b: String): Int {
    val dp = Array(a.length + 1) { IntArray(b.length + 1) }  // row 0 and column 0 are the base cases
    for (i in 1..a.length) {
        for (j in 1..b.length) {
            dp[i][j] = if (a[i - 1] == b[j - 1]) dp[i - 1][j - 1] + 1      // this is the LCS recurrence
                       else maxOf(dp[i - 1][j], dp[i][j - 1])
        }
    }
    return dp[a.length][b.length]
}
// Time: O(n * m)   Space: O(n * m)   More variants in the LCS, LIS & String DP topic

fun uniquePathsWithObstacles(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    val dp = IntArray(cols)
    dp[0] = if (grid[0][0] == 0) 1 else 0
    for (r in 0 until rows) {
        for (c in 0 until cols) {
            if (grid[r][c] == 1) {
                dp[c] = 0                             // an obstacle blocks every path through it
            } else if (c > 0) {
                dp[c] += dp[c - 1]                    // above (old dp[c]) + left (new dp[c - 1])
            }
        }
    }
    return dp[cols - 1]
}
// Time: O(rows * cols)   Space: O(cols)

fun minPathSum(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    val dp = Array(rows) { IntArray(cols) }
    dp[0][0] = grid[0][0]
    for (c in 1 until cols) dp[0][c] = dp[0][c - 1] + grid[0][c]     // first row: only from the left
    for (r in 1 until rows) dp[r][0] = dp[r - 1][0] + grid[r][0]     // first column: only from above
    for (r in 1 until rows) {
        for (c in 1 until cols) {
            dp[r][c] = grid[r][c] + minOf(dp[r - 1][c], dp[r][c - 1])
        }
    }
    return dp[rows - 1][cols - 1]
}
// Time: O(rows * cols)   Space: O(rows * cols), or O(cols) with one row

fun minimumTotal(triangle: List<List<Int>>): Int {
    val n = triangle.size
    val dp = IntArray(n + 1)                          // the extra slot acts as a zero row below the base
    for (row in n - 1 downTo 0) {
        for (i in 0..row) {
            dp[i] = triangle[row][i] + minOf(dp[i], dp[i + 1])   // go down or down-right
        }
    }
    return dp[0]
}
// Time: O(n²)   Space: O(n)
// Going bottom-up removes the need to handle edges and picks the answer at dp[0]

fun minFallingPathSum(matrix: Array<IntArray>): Int {
    val n = matrix.size
    var prev = matrix[0].copyOf()
    for (r in 1 until n) {
        val cur = IntArray(n)
        for (c in 0 until n) {
            var best = prev[c]                        // straight down
            if (c > 0) best = minOf(best, prev[c - 1])        // from the upper-left
            if (c < n - 1) best = minOf(best, prev[c + 1])    // from the upper-right
            cur[c] = matrix[r][c] + best
        }
        prev = cur
    }
    return prev.minOrNull()!!
}
// Time: O(n²)   Space: O(n)

fun maximalSquare(matrix: Array<CharArray>): Int {
    val rows = matrix.size
    val cols = matrix[0].size
    val dp = Array(rows + 1) { IntArray(cols + 1) }   // dp[r][c] = side of the largest square ending at (r - 1, c - 1)
    var side = 0
    for (r in 1..rows) {
        for (c in 1..cols) {
            if (matrix[r - 1][c - 1] == '1') {
                dp[r][c] = 1 + minOf(dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1])
                side = maxOf(side, dp[r][c])
            }
        }
    }
    return side * side
}
// Time: O(rows * cols)   Space: O(rows * cols)
// A square grows only as far as its smallest neighboring square allows

fun countSquares(matrix: Array<IntArray>): Int {
    val rows = matrix.size
    val cols = matrix[0].size
    val dp = Array(rows + 1) { IntArray(cols + 1) }
    var total = 0
    for (r in 1..rows) {
        for (c in 1..cols) {
            if (matrix[r - 1][c - 1] == 1) {
                dp[r][c] = 1 + minOf(dp[r - 1][c], dp[r][c - 1], dp[r - 1][c - 1])
                total += dp[r][c]                     // a square of side s adds s squares ending here
            }
        }
    }
    return total
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun calculateMinimumHP(dungeon: Array<IntArray>): Int {
    val rows = dungeon.size
    val cols = dungeon[0].size
    // dp[r][c] = minimum health needed when ENTERING cell (r, c)
    val dp = Array(rows + 1) { IntArray(cols + 1) { Int.MAX_VALUE } }
    dp[rows][cols - 1] = 1                            // after the last cell we need at least 1 health
    dp[rows - 1][cols] = 1
    for (r in rows - 1 downTo 0) {
        for (c in cols - 1 downTo 0) {
            val need = minOf(dp[r + 1][c], dp[r][c + 1]) - dungeon[r][c]
            dp[r][c] = maxOf(1, need)                 // health can never drop below 1
        }
    }
    return dp[0][0]
}
// Time: O(rows * cols)   Space: O(rows * cols)
// Going forward fails because the best prefix is not the best choice; working backward fixes that

fun longestPalindrome(s: String): String {
    if (s.isEmpty()) return ""
    val n = s.length
    val dp = Array(n) { BooleanArray(n) }             // dp[i][j] = s[i..j] is a palindrome
    var start = 0
    var maxLen = 1
    for (i in n - 1 downTo 0) {                       // i goes down so dp[i + 1][...] is ready
        for (j in i until n) {
            if (s[i] == s[j] && (j - i < 2 || dp[i + 1][j - 1])) {
                dp[i][j] = true
                if (j - i + 1 > maxLen) {
                    maxLen = j - i + 1
                    start = i
                }
            }
        }
    }
    return s.substring(start, start + maxLen)
}
// Time: O(n²)   Space: O(n²)
// Expanding around each center gives O(n²) time with O(1) space

fun countSubstrings(s: String): Int {
    val n = s.length
    val dp = Array(n) { BooleanArray(n) }
    var count = 0
    for (i in n - 1 downTo 0) {
        for (j in i until n) {
            if (s[i] == s[j] && (j - i < 2 || dp[i + 1][j - 1])) {
                dp[i][j] = true
                count++
            }
        }
    }
    return count
}
// Time: O(n²)   Space: O(n²)

fun maxProfitK(k: Int, prices: IntArray): Int {
    val n = prices.size
    if (n < 2 || k == 0) return 0
    if (k >= n / 2) {                                 // effectively unlimited transactions
        var profit = 0
        for (i in 1 until n) {
            if (prices[i] > prices[i - 1]) profit += prices[i] - prices[i - 1]
        }
        return profit
    }

    val dp = Array(k + 1) { IntArray(n) }             // dp[t][i] = best profit with at most t trades by day i
    for (t in 1..k) {
        var bestBuy = -prices[0]                      // max over j of (dp[t - 1][j] - prices[j])
        for (i in 1 until n) {
            dp[t][i] = maxOf(dp[t][i - 1], prices[i] + bestBuy)    // no sale today, or sell today
            bestBuy = maxOf(bestBuy, dp[t - 1][i] - prices[i])      // best moment to buy so far
        }
    }
    return dp[k][n - 1]
}
// Time: O(k * n)   Space: O(k * n), or O(n) keeping two layers

fun longestIncreasingPath(matrix: Array<IntArray>): Int {
    val rows = matrix.size
    val cols = matrix[0].size
    val memo = Array(rows) { IntArray(cols) }         // 0 means not computed
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))

    fun dfs(r: Int, c: Int): Int {
        if (memo[r][c] != 0) return memo[r][c]
        var best = 1
        for ((dr, dc) in dirs) {
            val nr = r + dr
            val nc = c + dc
            if (nr in 0 until rows && nc in 0 until cols && matrix[nr][nc] > matrix[r][c]) {
                best = maxOf(best, 1 + dfs(nr, nc))
            }
        }
        memo[r][c] = best
        return best
    }

    var answer = 0
    for (r in 0 until rows) for (c in 0 until cols) answer = maxOf(answer, dfs(r, c))
    return answer
}
// Time: O(rows * cols)   Space: O(rows * cols)
// Strictly increasing paths cannot cycle, so memoization is safe

fun maxCoins(nums: IntArray): Int {
    val n = nums.size
    val arr = IntArray(n + 2)                         // pad both ends with 1
    arr[0] = 1
    arr[n + 1] = 1
    for (i in 0 until n) arr[i + 1] = nums[i]

    // dp[l][r] = best coins from bursting every balloon strictly between l and r
    val dp = Array(n + 2) { IntArray(n + 2) }
    for (len in 2..n + 1) {                           // distance between l and r
        for (l in 0..n + 1 - len) {
            val r = l + len
            for (k in l + 1 until r) {                // k is the LAST balloon to burst in (l, r)
                val coins = dp[l][k] + arr[l] * arr[k] * arr[r] + dp[k][r]
                dp[l][r] = maxOf(dp[l][r], coins)
            }
        }
    }
    return dp[0][n + 1]
}
// Time: O(n³)   Space: O(n²)
// Thinking of the LAST balloon makes the left and right parts independent

fun generate(numRows: Int): List<List<Int>> {
    val rows = ArrayList<List<Int>>()
    for (i in 0 until numRows) {
        val row = MutableList(i + 1) { 1 }            // edges are always 1
        for (j in 1 until i) {
            row[j] = rows[i - 1][j - 1] + rows[i - 1][j]    // sum of the two numbers above
        }
        rows.add(row)
    }
    return rows
}
// Time: O(n²)   Space: O(n²)

// Out of Boundary Paths: count ways to leave the grid within maxMove moves
fun findPaths(m: Int, n: Int, maxMove: Int, startRow: Int, startColumn: Int): Int {
    val mod = 1_000_000_007L
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    var cur = Array(m) { LongArray(n) }               // cur[r][c] = ways to be at (r, c) after the moves so far
    cur[startRow][startColumn] = 1
    var total = 0L
    repeat(maxMove) {
        val next = Array(m) { LongArray(n) }
        for (r in 0 until m) {
            for (c in 0 until n) {
                val ways = cur[r][c]
                if (ways == 0L) continue
                for ((dr, dc) in dirs) {
                    val nr = r + dr
                    val nc = c + dc
                    if (nr !in 0 until m || nc !in 0 until n) {
                        total = (total + ways) % mod          // this move leaves the grid
                    } else {
                        next[nr][nc] = (next[nr][nc] + ways) % mod
                    }
                }
            }
        }
        cur = next
    }
    return total.toInt()
}
// Time: O(maxMove * m * n)   Space: O(m * n) with two layers
